def get_query_params(url: str) -> dict:
    """
    Extract query parameters from a URL string and return them as a dictionary.

    Args:
        url (str): The URL string containing query parameters

    Returns:
        dict: Dictionary of query parameters with unique keys

    Example:
        get_query_params("https://example.com/path?name=alice&age=30") 
        returns {'name': 'alice', 'age': '30'}
    """
    # Handle empty or None URL
    if not url or not isinstance(url, str):
        return {}

    # Find the query string part (after the question mark)
    query_start = url.find('?')
    if query_start == -1:
        return {}

    query_string = url[query_start + 1:]

    params = {}
    pairs = query_string.split('&')

    for pair in pairs:
        if '=' in pair:
            key, value = pair.split('=', 1)  # Split on first '=' only
            params[key] = value

    return params
