def diff_dicts(dict1, dict2):
    """
    Compare two flat dictionaries and return a dictionary with three keys:
    - 'added': keys present in dict2 but not in dict1
    - 'removed': keys present in dict1 but not in dict2
    - 'changed': keys present in both dictionaries with different values

    Args:
        dict1 (dict): First dictionary to compare
        dict2 (dict): Second dictionary to compare

    Returns:
        dict: Dictionary with 'added', 'removed', 'changed' keys containing lists of keys
    """
    added = []
    removed = []
    changed = []

    # Find keys that are in dict2 but not in dict1
