def find_longest_palindromic_substring(s: str) -> str:
    if not s:
        return ""

    def expand_around_center(left: int, right: int) -> str:
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        # Return the palindrome substring (right - left - 1 characters)
        return s[left + 1:right]

    longest = ""

    for i in range(len(s)):
        # Odd length palindrome (single character center)
        palindrome1 = expand_around_center(i, i)
        # Even length palindrome (between two characters)
        palindrome2 = expand_around_center(i, i + 1)

        # Choose the longer one, or the first one if equal length
        current_longest = palindrome1 if len(palindrome1) > len(palindrome2) else palindrome2

        if len(current_longest) > len(longest):
            longest = current_longest

    return longest

