def xml_to_dict(xml_string):
    """
    Parse a simple, well-formed XML string into a Python dictionary.

    Ignores attributes. Nested tags become dictionaries, text content becomes strings.
    Multiple children with the same tag form a list.

    Args:
        xml_string (str): A well-formed XML string

    Returns:
        dict: A dictionary representation of the XML structure
    """
    def parse_element(element):
        # If element has no children, return just the text content
        if len(element) == 0:
            return element.text.strip() if element.text and element.text.strip() else None

        result = {}

        # Process each child element
        for child in element:
            child_tag = child.tag
            child_text = child.text.strip() if child.text and child.text.strip() else None

            # If this tag already exists in the result, make it a list
            if child_tag in result:
                if isinstance(result[child_tag], list):
                    result[child_tag].append(parse_element(child))
                else:
                    # Convert single value to list
                    old_value = result[child_tag]
                    result[child_tag] = [old_value]
                    result[child_tag].append(parse_element(child))
            else:
                # First occurrence of this tag
                result[child_tag] = parse_element(child)

        # If the result is empty (only text content), return the text
        if not result and element.text and element.text.strip():
            return element.text.strip()

        return result

    # Parse the XML string
    root = ET.fromstring(xml_string)

    # Parse the root element
    return parse_element(root)

