def simulate_first_fit_allocator(memory_size, operations):
    """
    Simulates a first-fit memory allocator.

    Args:
        memory_size (int): Total size of memory (contiguous block from 0 to memory_size-1)
        operations (list): List of operations as tuples ('alloc', id, size) or ('free', id)

    Returns:
        list: List of results for alloc operations (starting index or -1 if failed)
    """
    # Track allocated blocks: id -> (start, size, end)
    allocated = {}
    results = []

    def find_first_fit(size):
        """Find the first contiguous block of at least 'size' bytes."""
        for start in range(memory_size - size + 1):
            # Check if this block is free (not occupied by any allocated block)
            is_free = True
            for (s, e) in allocated.values():
                if not (start >= e or start + size <= s):
                    is_free = False
                    break
            if is_free:
                return start
        return -1

    for op in operations:
        if op[0] == 'alloc':
            alloc_id = op[1]
            size = op[2]
            start = find_first_fit(size)
            if start == -1:
                results.append(-1)
            else:
                # Allocate the block
                allocated[alloc_id] = (start, start + size)
                results.append(start)
        elif op[0] == 'free':
            alloc_id = op[1]
            if alloc_id in allocated:
                del allocated[alloc_id]

    return results
