    """
    Compute the edit distance between two strings and return the distance and a list of operations
    to transform s1 into s2.

    Args:
        s1 (str): First string
        s2 (str): Second string

    Returns:
        tuple: (distance, operations) where operations is a list of strings describing each operation
    """
    if not s1:
        return (len(s2), [('insert', s2, 0)])

    if not s2:
        return (len(s1), [('delete', '', 0) for _ in range(len(s1))])

    # Create DP table for edit distance
    m, n = len(s1), len(s2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Initialize base cases
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    # Fill DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(
                    dp[i-1][j],      # delete
                    dp[i][j-1],      # insert
                    dp[i-1][j-1]     # replace
                )

    # Reconstruct operations
    operations = []
    i, j = m, n

    while i > 0 and j > 0:
        if s1[i-1] == s2[j-1]:
            # No operation needed
            i -= 1
            j -= 1
        else:
            if dp[i-1][j] == dp[i][j] - 1:
                # Delete from s1
