def strongly_connected_components(graph):
    """
    Find strongly connected components (SCCs) in a directed graph using Kosaraju's algorithm.

    Args:
        graph (dict): Adjacency list representation of a directed graph.
                     Keys are nodes, values are sets/lists of adjacent nodes.

    Returns:
        list: List of sets, where each set represents a strongly connected component.
    """
    if not graph:
        return []

    # Step 1: Get all nodes
    nodes = list(graph.keys())

    # Step 2: First DFS to get finishing times (order of nodes by completion)
    def dfs1(node, visited, order):
        visited.add(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                dfs1(neighbor, visited, order)
        order.append(node)

    visited = set()
    order = []
    for node in nodes:
        if node not in visited:
            dfs1(node, visited, order)

    # Step 3: Build transpose graph (reverse edges)
    transpose = {}
    for node in nodes:
        transpose[node] = set()
    for node in nodes:
        for neighbor in graph.get(node, []):
            transpose[neighbor].add(node)

    # Step 4: Second DFS on transpose graph in reverse order of finishing times
    def dfs2(node, visited, component):
        visited.add(node)
        component.append(node)
        for neighbor in transpose.get(node, []):
            if neighbor not in visited:
                dfs2(neighbor, visited, component)

    result = []
    visited = set()

    # Process nodes in reverse order of finishing times
    for node in reversed(order):
        if node not in visited:
            component = []
            dfs2(node, visited, component)
            if component:
                result.append(set(component))

    return result
