def max_bipartite_matching(graph):
    """
    Find the size of the maximum matching in a bipartite graph using the Hopcroft-Karp algorithm.

    Args:
        graph (dict): Dictionary mapping left nodes to lists of right nodes.
                     Left nodes are keys, right nodes are values (list of neighbors).

    Returns:
        int: Size of the maximum matching.

    Example:
        graph = {0: [1, 2], 1: [2], 2: [0, 3], 3: []}
        max_bipartite_matching(graph) -> 2
    """
    if not graph:
        return 0

    left_nodes = list(graph.keys())
    right_nodes = set(node for right_nodes in graph.values() for node in right_nodes)

    # Create adjacency list for right nodes
    right_adj = {node: [] for node in right_nodes}
    for left_node, neighbors in graph.items():
        for right_node in neighbors:
            right_adj[right_node].append(left_node)

    # Matchings: left_node -> right_node
    match_right = {}  # right_node -> left_node
    match_left = {}   # left_node -> right_node

    def bfs():
        """Build alternating tree using BFS"""
        parent = {}
        queue = []
        visited = set()

        # Start BFS from all left nodes
        for left_node in left_nodes:
            if left_node not in match_left:
                parent[left_node] = None
                queue.append(left_node)
                visited.add(left_node)

        while queue:
            curr_left = queue.pop(0)
            if curr_left in match_left:
                right_node = match_left[curr_left]
                if right_node not in visited:
                    visited.add(right_node)
                    parent[right_node] = curr_left
                    queue.append(right_node)
            else:
                # No match, so we can extend
                for neighbor in graph[curr_left]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        parent[neighbor] = curr_left
                        queue.append(neighbor)

        return parent

    def dfs(left_node, parent):
        """Find augmenting path using DFS"""
        if left_node in match_left:
            right_node = match_left[left_node]
            if right_node in parent:
                # Found an augmenting path
                return True
            else:
                # Try to extend
                return dfs(parent[right_node], parent)
        return False

    # Main Hopcroft-Karp algorithm
    matching_size = 0

    while True:
        parent = bfs()
        if not parent:
            break

        # Find augmenting paths and update matching
        for left_node in left_nodes:
            if left_node not in match_left:
                # Try to find augmenting path from left_node
                path = []
                curr = left_node
                while curr in parent:
                    path.append(curr)
                    curr = parent[curr]

                # If we found a path, augment it
                if path:
                    # Reverse path to get augmenting path
                    augment_path = []
                    for i in range(len(path) - 1, -1, -1):
                        augment_path.append(path[i])

                    # Update matching
                    for i in range(0, len(augment_path) - 1, 2):
                        left_node = augment_path[i]
                        right_node = augment_path[i + 1]
                        if right_node in match_right:
                            match_left[match_right[right_node]] = None
                        match_left[left_node] = right_node
                        match_right[right_node] = left_node
                    matching_size += 1

    return matching_size

