def solve_linear_system(A, b):
    n = len(b)

    # Convert A and b to lists of floats for consistency
    A = [[float(a) for a in row] for row in A]
    b = [float(val) for val in b]

    # Create augmented matrix [A | b]
    aug = [row[:] for row in A]
    for i in range(n):
        aug[i].append(b[i])

    # Gaussian elimination with partial pivoting
    for col in range(n):
        # Find pivot row (row with largest absolute value in current column)
        pivot_row = col
        for row in range(col + 1, n):
            if abs(aug[row][col]) > abs(aug[pivot_row][col]):
                pivot_row = row

        # Swap rows if needed
        if pivot_row != col:
            aug[col], aug[pivot_row] = aug[pivot_row], aug[col]

        # Check if pivot is zero (no unique solution)
        if abs(aug[col][col]) < 1e-12:
            return None

        # Eliminate entries below pivot
        for row in range(col + 1, n):
            factor = aug[row][col] / aug[col][col]
            for j in range(col, n + 1):
                aug[row][j] -= factor * aug[col][j]

    # Back substitution
    x = [0.0] * n
    for i in range(n - 1, -1, -1):
        sum_val = 0.0
        for j in range(i + 1, n):
            sum_val += aug[i][j] * x[j]
        x[i] = (aug[i][n] - sum_val) / aug[i][i]

    # Round to 6 decimal places
    return [round(val, 6) for val in x]

