def cron_parser(cron_expr: str) -> dict:
    """
    Parse a full 5-field cron expression and return a dict with valid values for each field.

    Args:
        cron_expr (str): A full cron expression in format "minute hour day month weekday"

    Returns:
        dict: Keys 'minute', 'hour', 'day', 'month', 'weekday' mapping to sorted lists of valid values

    Supports:
        * - all values
        ranges: 1-5
        steps: */15
        lists: 1,3,5
        combinations: 1-5/2
    """
    fields = cron_expr.strip().split()
    if len(fields) != 5:
        raise ValueError("Cron expression must have exactly 5 fields")

    result = {
        'minute': [],
        'hour': [],
        'day': [],
        'month': [],
        'weekday': []
    }

    def parse_field(field_str):
        values = []
        field_str = field_str.strip()

        # Handle * (all values)
        if field_str == '*':
            return list(range(1, 61)) if field_str == 'minute' else \
                   list(range(1, 25)) if field_str == 'hour' else \
                   list(range(1, 32)) if field_str == 'day' else \
                   list(range(1, 13)) if field_str == 'month' else \
                   list(range(1, 8)) if field_str == 'weekday' else []

        # Handle ranges: 1-5, 1-5/2
        if '-' in field_str:
            parts = field_str.split('-')
            start, end = int(parts[0]), int(parts[1])
            if '/' in field_str:
                step_part = field_str.split('/')[1]
                step = int(step_part) if step_part else 1
                values = list(range(start, end + 1, step))
            else:
                values = list(range(start, end + 1))
        # Handle steps: */15
        elif field_str.startswith('/'):
            step = int(field_str[1:])
            if field_str == '*/15':
                if field_str == 'minute':
                    values = list(range(0, 60, step))
                elif field_str == 'hour':
                    values = list(range(0, 24, step))
                elif field_str == 'day':
                    values = list(range(1, 32, step))
                elif field_str == 'month':
                    values = list(range(1, 13, step))
                elif field_str == 'weekday':
                    values = list(range(1, 8, step))
            else:
                step = int(field_str[1:])
                if field_str == 'minute':
                    values = list(range(0, 60, step))
                elif field_str == 'hour':
                    values = list(range(0, 24, step))
                elif field_str == 'day':
                    values = list(range(1, 32, step))
                elif field_str == 'month':
                    values = list(range(1, 13, step))
                elif field_str == 'weekday':
                    values = list(range(1, 8, step))
        # Handle lists: 1,3,5
        else:
            # Split by comma and convert to integers
            if ',' in field_str:
                values = [int(x.strip()) for x in field_str.split(',')]
            else:
                # Handle single values
                values = [int(field_str)]

        # Ensure values are valid for the field
        if field_str == 'minute':
            values = [v for v in values if 0 <= v < 60]
        elif field_str == 'hour':
            values = [v for v in values if 0 <= v < 24]
        elif field_str == 'day':
            values = [v for v in values if 1 <= v <= 31]
        elif field_str == 'month':
            values = [v for v in values if 1 <= v <= 12]
        elif field_str == 'weekday':
            values = [v for v in values if 1 <= v <= 7]

        # Sort values
        values.sort()
        return values

    # Parse each field
    result['minute'] = parse_field(fields[0])
    result['hour'] = parse_field(fields[1])
    result['day'] = parse_field(fields[2])
    result['month'] = parse_field(fields[3])
    result['weekday'] = parse_field(fields[4])

    return result
